INSERT INTO `alert_rule`(`id`, `name`, `expr`, `last`, `summary`, `description`, `receiver`, `build_in`, `unit`, `seq`, `method`, `state`, `type`, `inr`, `timeout`, `auto_expired`, `sched_enable`, `sched_days`, `sched_stime`, `sched_etime`, `notify_active`, `notify_expired`, `trb_shot`, `condition`, `ext_labels`,`param`)
VALUES
    (1, 'Default snmptrap', '1.3.6.1', 3600, '{{$message}}', '{{$variables}}', '', '1', 2, NULL, '', 1, 3, 0, 300, 1, 1, '1,2,3,4,5,6,7', '00:00', '23:59', 0, 0, '', '[{\"id\":3,\"weight\":1,\"operator\":\"=~\",\"value\":\".*\"}]', '','{"dataLink":[]}'),
    (2, 'Endpoint down', 'up{endpoint!=\"\",datacenter=\"xin_xi_gang_DC\",module!=\"CM-Sync-Redis\"}', 60, 'The endpoint is down, endpointId is {{$labels.endpoint}}.', '\"The endpoint is down, the detailed information\nAsset :  {{$labels.asset}},\nProject:  {{$labels.project}},\nModule:  {{$labels.module}},\nData center:  {{$labels.datacenter}},\nEndpointId: {{$labels.endpoint}}.\"', '34,70,98', '0', 2, NULL, '1', 1, 1, 120, 300, 1, 1, '3', '00:00', '23:59', 1, 1, '', '[{\"id\":1,\"weight\":1,\"operator\":\"!=\",\"value\":\"1.0\"}]', '','{"dataLink":[]}'),
    (3, 'NZ-CPU-Usage', '(1-avg(irate(node_cpu_seconds_total{mode=\"idle\",asset=~\"Nezha Server.*\"}[5m])) by(asset)) * 100', 60, 'More than 80 cpu usage {{$labels.asset}}', 'If the CPU usage of the device exceeds 80 for 60 seconds, the alert will be generated\nAsset :  {{$labels.asset}}.', '34,98', '0', 3, '0b4e8188-13d1-4b93-a825-10d3380e4abb', '1', 1, 1, 30, 300, 1, 0, '1,2,3,4,5,6,7', '00:00', '23:59', 0, 0, '', '[{\"id\":2,\"weight\":2,\"operator\":\">\",\"value\":\"80.0\"}]', '','{"dataLink":[]}'),
    (4, 'NZ-Disk-space', '100-(node_filesystem_free_bytes{fstype=~\"ext4|xfs\",asset=~\"Nezha Server.*\"}/node_filesystem_size_bytes {fstype=~\"ext4|xfs\",asset=~\"Nezha Server.*\"}*100)', 60, 'More than 80 disk usage {{$labels.asset}}', 'If the device\'s hard disk utilization rate exceeds 80% for 60 second\nAsset :  {{$labels.asset}},\nProject:  {{$labels.project}},\nModule:  {{$labels.module}},\nData center:  {{$labels.datacenter}},\nEndpointId: {{$labels.endpoint}},\nFstype : {{$labels.fstype}}', '98,34', '0', 3, '0b4e8188-13d1-4b93-a825-10d3380e4abb', '1', 1, 1, 30, 300, 1, 0, '1,2,3,4,5,6,7', '00:00', '23:59', 0, 0, '', '[{\"id\":2,\"weight\":2,\"operator\":\">\",\"value\":\"80.0\"}]', '','{"dataLink":[]}'),
(5, 'NZ-Memory-space', '((node_memory_MemTotal_bytes{asset=~\"Nezha Server.*\"} -(node_memory_MemFree_bytes{asset=~\"Nezha Server.*\"}+node_memory_Buffers_bytes{asset=~\"Nezha Server.*\"}+node_memory_Cached_bytes{asset=~\"Nezha Server.*\"}) )/node_memory_MemTotal_bytes{asset=~\"Nezha Server.*\"} ) * 100', 60, 'More than 80 memory usage {{$labels.asset}}', 'If the device\'s memory utilization rate exceeds 80% for 60 seconds, the alert will be generated\nAsset :  {{$labels.asset}},\nProject:  {{$labels.project}},\nModule:  {{$labels.module}},\nData center:  {{$labels.datacenter}},\nEndpointId: {{$labels.endpoint}}', '98,34', '0', 3, '0b4e8188-13d1-4b93-a825-10d3380e4abb', '1', 1, 1, 30, 300, 1, 0, '1,2,3,4,5,6,7', '00:00', '23:59', 0, 0, '', '[{\"id\":2,\"weight\":2,\"operator\":\">\",\"value\":\"80.0\"}]', '','{"dataLink":[]}'),
(6, 'NZ-Prometheus-down', 'label_replace(up{application=~\"prometheus\"},\"asset\",\"$1\",\"instance\",\"(.*):\\\\d+\")', 60, 'Prometheus is down, IP is {{$labels.host}}', 'An alert is generated, when the Prometheus component service in a data center of the NEZHA system does not run for one minut\nPrometheus is down\nHost :  {{$labels.host}},\nPort:  {{$labels.port}},\nData center:  {{$labels.datacenter}},\nType: {{$labels.type}}.', '98,34', '0', 2, '0b4e8188-13d1-4b93-a825-10d3380e4abb', '1', 1, 1, 30, 300, 1, 0, '1,2,3,4,5,6,7', '00:00', '23:59', 0, 0, '', '[{\"id\":1,\"weight\":1,\"operator\":\"!=\",\"value\":\"1.0\"}]', '','{"dataLink":[]}'),
(7, 'CM-API Average Request Latency', 'increase(http_server_requests_seconds_sum{module=\"CM-API\",exception=\"None\"}[5m])/increase(http_server_requests_seconds_count{module=\"CM-API\",exception=\"None\"}[5m]) ', 60, 'CM-API Average Request Latency {{$labels.asset}}', 'Bifang-CM平均请求>180s \nCM-API Average Request Latency', '', '0', 30, NULL, '', 1, 1, 60, 300, 1, 0, '', '00:00', '23:59', 0, 0, '', '[{\"id\":2,\"weight\":1,\"operator\":\">\",\"value\":\"180.0\"}]', '','{"dataLink":[]}');
